beforeExample:
public class MyClass {
    public void printLine() {
        System.out.println("Hello" + System.getProperty("line.separator") + "World");
    }
}

afterExample:
public class MyClass {
    public void printLine() {
        System.out.println("Hello" + System.lineSeparator() + "World");
    }
}

